/** Missing-input guard: a tool executed without its subject refuses with a RangeError (never a TypeError). */
const need = (i: ToolInput, ...keys: string[]): void => { const gaps = keys.filter((k) => i[k] === undefined || i[k] === null || i[k] === ""); if (gaps.length) throw new RangeError(`26.2 tool needs ${gaps.join(", ")}`); };
const at = (i: ToolInput, ctx: CommandContext, key = "at"): string => str(i, key) || ctx.now;
const obj = (i: ToolInput, k: string): Record<string, unknown> => { const v = i[k]; if (!v || typeof v !== "object") throw new RangeError(`26.2 tool needs ${k} (object)`); return v as Record<string, unknown>; };
const arr = <T>(i: ToolInput, k: string): T[] => (Array.isArray(i[k]) ? (i[k] as T[]) : []);
const put = <T>(rt: ToolRuntime, ctx: CommandContext, kind: string, id: string, v: T): T => rt.store.put(kind, id, v as unknown as Record<string, unknown>, ctx.actor, ctx.now).data as unknown as T;
const loadClosing = (i: ToolInput, rt: ToolRuntime): Closing => { need(i, "closing_id"); const r = rt.store.get("closings", str(i, "closing_id")); if (!r) throw new RangeError(`no closing ${str(i, "closing_id")} (runPreSessionChecks op=schedule opens it)`); return r.data as unknown as Closing; };
const loadSession = (i: ToolInput, rt: ToolRuntime, c: Closing): SigningSession => { const id = str(i, "session_id") || c.session_ids.at(-1) || ""; const r = rt.store.get("signing_sessions", id); if (!r) throw new RangeError(`no signing_session ${id || "(none)"} (openSigningSession first)`); return r.data as unknown as SigningSession; };
const loadENote = (rt: ToolRuntime, c: Closing): ENote => { const r = rt.store.list("enotes", (d) => d.closing_id === c.closing_id).at(-1); if (!r) throw new RangeError(`no eNote for closing ${c.closing_id} (monitorSession op=enote_created seeds it)`); return r.data as unknown as ENote; };
const loadRecording = (i: ToolInput, rt: ToolRuntime): Recording => { need(i, "recording_id"); const r = rt.store.get("recordings", str(i, "recording_id")); if (!r) throw new RangeError(`no recording ${str(i, "recording_id")} (submitERecording op=open first)`); return r.data as unknown as Recording; };
const eligibilityRows = (i: ToolInput, rt: ToolRuntime): EclosingEligibility[] => (Array.isArray(i.eligibility) ? (i.eligibility as EclosingEligibility[]) : rt.store.list("eclosing_eligibility").map((r) => r.data as unknown as EclosingEligibility));
const consentOf = (i: ToolInput, rt: ToolRuntime, c: Closing): ClosingEsignConsent | null => (i.consent && typeof i.consent === "object" ? (i.consent as ClosingEsignConsent) : (rt.store.list("consents", (d) => d.application_id === c.application_id && d.kind === "esign").at(-1)?.data as unknown as ClosingEsignConsent | undefined) ?? null);
const eregistry = (rt: ToolRuntime): ERegistryPort26 => { try { return service<ERegistryPort26>(rt, "26.2.eregistry"); } catch { const f = new FakeERegistry26(); (rt.services as Record<string, unknown>)["26.2.eregistry"] = f; return f; } };
const ronPlatform = (rt: ToolRuntime): RonPlatformPort => { try { return service<RonPlatformPort>(rt, "26.2.ron"); } catch { const f = new FakeRonPlatform(); (rt.services as Record<string, unknown>)["26.2.ron"] = f; return f; } };
const evault = (rt: ToolRuntime) => rt.ports.evault ?? (() => { const f = new FakeEvault(); (rt.ports as Record<string, unknown>).evault = f; return f; })();
const ronInput = (i: ToolInput, c: Pick<Closing, "state" | "county_fips" | "tx_50a6">, rows: readonly EclosingEligibility[], agentId: string): ClosingTypeInput => ({
  state: c.state, county_fips: c.county_fips, tx_50a6: c.tx_50a6, enote_eligible: i.enote_eligible !== false, proposed_closing_type: (str(i, "proposed_closing_type") as ClosingType) || "ron", borrower_election: (i.borrower_election as ClosingType | undefined) ?? null,
  signers: arr(i, "signers"), county_accepts_ron_instruments: i.county_accepts_ron_instruments !== false, title_no_ron_exception: i.title_no_ron_exception !== false, agent: (i.agent as EclosingEligibility | undefined) ?? rows.find((r) => r.settlement_agent_party_id === agentId) ?? null,
  ron_provider_available: i.ron_provider_available !== false, notary: (i.notary as ClosingTypeInput["notary"] | undefined) ?? null, counsel_confirmation: (i.counsel_confirmation as ClosingTypeInput["counsel_confirmation"] | undefined) ?? null, in_person_enotarization_valid: i.in_person_enotarization_valid !== false,
  ...(i.consent_withdrawn !== undefined ? { consent_withdrawn: flag(i, "consent_withdrawn") } : {}), ...(i.session_failure !== undefined ? { session_failure: flag(i, "session_failure") } : {}) });
const unlistedWithoutCounsel = (i: ToolInput): boolean => { const st = str(i, "state") || (typeof i.closing === "object" && i.closing ? String((i.closing as Record<string, unknown>).state ?? "") : ""); return !!st && !FNMA_RON_STATES.includes(st) && str(i, "proposed_closing_type") === "ron" && flag(i, "treat_as_ron_eligible") && !i.counsel_confirmation; };

